"use server";

import { revalidatePath, revalidateTag } from "next/cache";

const backend_url = "http://localhost:3001";

//createuser function
export default async function Bchandlesubmit(formData: any) {
  try {
    const response = await fetch(`${backend_url}/create-user`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(formData),
    });

    const data = await response.json();
     revalidatePath("/adduser");
    //revalidateTag("users" as any);
    return { success: true, data };
  } catch (error) {
    console.error(error);
    return { success: false, error };
  }
}

//get user fucniton
export async function Bcgetuser() {
  try {
    //we are simulating delay if we see spinner then suspense and streaming is working fine
    //await new Promise((res) => setTimeout(res, 3000));
    const response = await fetch(`${backend_url}/get-user`, {
      next: { revalidate: 60, tags: ["users"] }, //using isr
    });
    const data = await response.json();

    return { success: true, data };
  } catch (error) {
    console.error(error);
    return { success: false, error };
  }
}
